local db = json.load_file(DATA) or {}
if db.version == nil then          -- data from the test builds (before 1.0): start clean; later versions keep it
    db = {}
end
db.version = VERSION
db.slots = db.slots or {}
db.log = db.log or {}
local function save_db() json.dump_file(DATA, db) end
local function log(s)
    table.insert(db.log, os.date("%Y-%m-%d %H:%M:%S") .. "  " .. s)
    while #db.log > 40 do table.remove(db.log, 1) end
    save_db()
end
local status = "load a save"

------------------------------------------------------------------------
-- upgrade tables: a 13-entry table (4 smith types x 3 steps + the dragonforge level) for every spoil,
-- added to ItemManager._WeaponEnhanceDict / _ArmorEnhanceDict like the game's own tables. Spoils have no tables of
-- their own, so an existing entry for one of them is ours (an earlier script instance) and is replaced.
------------------------------------------------------------------------
local TD = { w = sdk.find_type_definition("app.WeaponEnhanceParam"), a = sdk.find_type_definition("app.ArmorEnhanceParam") }
local DICT = { w = "_WeaponEnhanceDict", a = "_ArmorEnhanceDict" }
local ready = { w = 0, a = 0 }
-- level 1 steps (Vernworth): no bonus, weight rate 100% (neutral). The game computes the weight as
-- (base weight + step weights) x rate, so the level-3 steps carry minus half the base weight.
local NO_BONUS = { _WeightRate = 100 }
local function make_param(kind, id, typ, no, fields)
    local p = sdk.create_instance(TD[kind]:get_full_name()):add_ref()
    p:set_field("_ItemId", id); p:set_field("_Type", typ); p:set_field("_EnhanceNo", no)
    for k, v in pairs(fields) do p:set_field(k, v) end
    return p
end
local function aset(arr, i, v)
    if not pcall(function() arr[i] = v end) then arr:call("SetValue(System.Object, System.Int32)", v, i) end
end
local function inject_tables()
    local im = sdk.get_managed_singleton("app.ItemManager")
    if not im then return end
    local r = { w = 0, a = 0 }
    for _, kind in ipairs({ "w", "a" }) do
        local dict = im:get_field(DICT[kind])
        if not dict or (dict:call("get_Count") or 0) == 0 then return end
        for id, f in pairs(FORGE) do
            if f[1] == kind then
                local arr = sdk.create_managed_array(TD[kind], 13):add_ref()
                local i = 0
                for typ = 0, 3 do
                    for no = 0, 2 do
                        local fields = typ == 0 and NO_BONUS or (typ == 1 and f[4][no + 1] or f[5][no + 1])
                        aset(arr, i, make_param(kind, id, typ, no, fields)); i = i + 1
                    end
                end
                aset(arr, 12, make_param(kind, id, ENH_UNLIMIT, 0, f[3]))
                dict:call("set_Item", id, arr)
                r[kind] = r[kind] + 1
            end
        end
    end
    ready = r
end

-- blacksmiths and the Dragonforged don't offer upgrades for spoils: while one of their menus is open
-- (TalkEventPlayer ...EnhancementNode / ...DragonForgeNode run every frame then) the game is told a spoil has no
-- upgrade data. Everywhere else the truth, because the inventory uses the same question for the upgrade marks.
local smithSeen = -100
local function smith_open() return os.clock() - smithSeen < 0.5 end
for _, m in ipairs({ "startEnhancementNode", "updateEnhancementNode", "startDragonForgeNode", "updateDragonForgeNode" }) do
    pcall(function()
        sdk.hook(sdk.find_type_definition("app.TalkEventPlayer"):get_method(m), function() smithSeen = os.clock() end,
            function(r) return r end)
    end)
end
-- item ids whose card is being built right now for an unforged copy (no upgrade rings for those)
local uiUnforged = {}
for _, m in ipairs({ "isExistWeaponEnhanceData", "isExistArmorEnhanceData" }) do
    pcall(function()
        local hideNext = false
        sdk.hook(sdk.find_type_definition("app.ItemManager"):get_method(m), function(args)
            local id = sdk.to_int64(args[3]) & 0xFFFFFFFF
            hideNext = FORGE[id] ~= nil and (uiUnforged[id] ~= nil or smith_open())
        end, function(r)
            if hideNext then hideNext = false; return sdk.to_ptr(0) end
            return r
        end)
    end)
end

------------------------------------------------------------------------
-- items: StorageMasterData._Param (StorageData)._Enhance (_Num, _Type0.._Type2), written in place.
-- A dragonforged item is upgrade level 4 (like a normal dragonforged item); the type of its three steps = forge level.
------------------------------------------------------------------------
local SM_T = sdk.find_type_definition("app.ItemManager.StorageMasterData")
local SD_T = sdk.find_type_definition("app.ItemDefine.StorageData")
local EP_T = sdk.find_type_definition("app.ItemDefine.EnhanceParam")
local OFF_ENH = SM_T:get_field("_Param"):get_offset_from_base() + SD_T:get_field("_Enhance"):get_offset_from_fieldptr()
local OFF_E = {}
for _, f in ipairs({ "_Num", "_Type0", "_Type1", "_Type2" }) do OFF_E[f] = OFF_ENH + EP_T:get_field(f):get_offset_from_fieldptr() end
local function forged_state(level) local t = level - 1; return { 4, t, t, t } end
-- forge level of an item's upgrade state: 0 = not forged, else 1..3 (old "Dragon" steps count as 3)
local function level_of(e) if e[1] ~= 4 then return 0 end return math.min(e[2], 2) + 1 end
local PLAYER = "ch000000_00"
local MAIN_PAWN = "ch100000_00"

local CHARA = {}
pcall(function()
    for _, f in ipairs(sdk.find_type_definition("app.CharacterID"):get_fields()) do
        if f:is_static() then local ok, v = pcall(f.get_data, f, nil); if ok and type(v) == "number" then CHARA[v] = f:get_name() end end
    end
end)

local function list_each(list, fn)
    if not list then return end
    for i = 0, (list:call("get_Count") or 0) - 1 do
        local ok, e = pcall(list.call, list, "get_Item", i)
        if ok and e ~= nil then fn(e) end
    end
end
-- every item of every storage member (you, pawns, storage box): { md, sid, item, chara, equipped }
local function all_items()
    local im = sdk.get_managed_singleton("app.ItemManager")
    local out = {}
    if not im then return out end
    list_each(im:call("getStorageMembers"), function(cid)
        list_each(im:call("getStorageMasterList(app.CharacterID)", cid), function(md)
            local sd = md:get_field("_Param")
            if sd then
                out[#out + 1] = { md = md, sid = sd:get_field("_StorageId"), item = sd:get_field("_ItemId"),
                    chara = CHARA[cid] or tostring(cid), equipped = sd:get_field("_IsEquipped") }
            end
        end)
    end)
    return out
end
local function by_sid()
    local by = {}
    for _, it in ipairs(all_items()) do by[tostring(it.sid)] = it end
    return by
end
local function read_enh(md)
    return { md:read_byte(OFF_E._Num), md:read_byte(OFF_E._Type0), md:read_byte(OFF_E._Type1), md:read_byte(OFF_E._Type2) }
end
local function write_enh(md, e)
    md:write_byte(OFF_E._Num, e[1]); md:write_byte(OFF_E._Type0, e[2]); md:write_byte(OFF_E._Type1, e[3]); md:write_byte(OFF_E._Type2, e[4])
end

-- equipped items also live as copies in each character's EquipData; refresh them like the blacksmith does
local function push_to_equipment(mds)
    local im = sdk.get_managed_singleton("app.ItemManager")
    if not im or #mds == 0 then return end
    list_each(im:call("getStorageMembers"), function(cid)
        local ok, ed = pcall(im.call, im, "getEquipData(app.CharacterID)", cid)
        local data = ok and ed and ed:get_field("Data")
        if data then
            for _, md in ipairs(mds) do
                pcall(data.call, data, "updateEnhanceEquip(app.ItemDefine.StorageData)", md:get_field("_Param"))
            end
        end
    end)
    pcall(function() im:call("applyEquipDataForCharacter()") end)
end

------------------------------------------------------------------------
-- forge list of the loaded save: cur[storage id] = { item, name, level 1..3, orig = {num, t0, t1, t2} }
-- db.slots[slot] = the list as it was when that save slot was written; db.live = the current list (for script resets)
------------------------------------------------------------------------
local cur, curSlot = {}, nil
local pawnForgeTest = false        -- debug test switch: forged items stay forged on pawns (not saved)
local function copy(t) local o = {}; for k, v in pairs(t) do o[k] = type(v) == "table" and copy(v) or v end; return o end
local function remember_live() db.live = { slot = curSlot, items = copy(cur) }; save_db() end

-- right after a load (before anything is applied) the items are exactly what the save file holds: a DLC spoil with
-- an upgrade there could only come from a forge that leaked into the save
local saveCheck = "save file check: no save loaded since the scripts started"
local function check_save_file(slot)
    local bad = {}
    for _, it in ipairs(all_items()) do
        local n = FORGE[it.item] and read_enh(it.md)[1] or 0
        if n ~= 0 then bad[#bad + 1] = string.format("%s (level %d)", FORGE[it.item][2], n) end
    end
    saveCheck = #bad == 0 and string.format("save file check (slot %s): clean", tostring(slot))
        or string.format("save file check (slot %s): %d DLC spoil(s) with an upgrade in the save file: %s - they are kept out on the next save",
            tostring(slot), #bad, table.concat(bad, ", "))
    if #bad > 0 then log(saveCheck) end
end
-- the game itself never upgrades a spoil, so a spoil at level 4 that isn't on the list was forged by this mod
local function adopt_untracked()
    local n = 0
    for _, it in ipairs(all_items()) do
        if FORGE[it.item] and not cur[tostring(it.sid)] and read_enh(it.md)[1] == 4 then
            cur[tostring(it.sid)] = { item = it.item, name = FORGE[it.item][2], level = level_of(read_enh(it.md)), orig = { 0, 0, 0, 0 } }
            n = n + 1
        end
    end
    return n
end
-- put the forge on every listed item (after a load and after each save)
local function apply_all()
    local by = by_sid()
    local found, changed = 0, {}
    for sid, r in pairs(cur) do
        local it = by[sid]
        if it and it.item == r.item then
            -- hired pawns (other players' pawns) never carry a modded dragonforge; your main pawn does
            local onPawn = it.chara:sub(1, 3) == "ch1" and it.chara ~= MAIN_PAWN and not pawnForgeTest
            local e = read_enh(it.md)
            if e[1] ~= 4 then r.orig = r.orig or e end
            local want = onPawn and (r.orig or { 0, 0, 0, 0 }) or forged_state(r.level or 3)
            r.onPawn = onPawn or nil
            if e[1] ~= want[1] or e[2] ~= want[2] or e[3] ~= want[3] or e[4] ~= want[4] then
                write_enh(it.md, want); changed[#changed + 1] = it.md
            end
            found = found + 1
        end
    end
    push_to_equipment(changed)
    return found
end
-- take the forge off again (while the game writes a save, and when the scripts unload); returns the found entries
local function strip_all()
    local by = by_sid()
    local kept, changed = {}, {}
    for sid, r in pairs(cur) do
        local it = by[sid]
        if it and it.item == r.item then
            write_enh(it.md, r.orig or { 0, 0, 0, 0 })
            changed[#changed + 1] = it.md
            kept[sid] = copy(r)
        end
    end
    push_to_equipment(changed)
    return kept, #changed
end

-- one dragonforge level more (up to 3); returns the new level
local function raise(it)
    local sid = tostring(it.sid)
    local r = cur[sid]
    if not r then
        r = { item = it.item, name = FORGE[it.item][2], level = 0, orig = read_enh(it.md) }
        cur[sid] = r
    end
    r.level = math.min((r.level or 3) + 1, 3)
    write_enh(it.md, forged_state(r.level))
    push_to_equipment({ it.md })
    remember_live()
    return r.level
end
local function unforge(sid)
    local r = cur[sid]
    if not r then return end
    local it = by_sid()[sid]
    if it and it.item == r.item then write_enh(it.md, r.orig or { 0, 0, 0, 0 }); push_to_equipment({ it.md }) end
    cur[sid] = nil
    remember_live()
    log("undid the dragonforge of " .. tostring(r.name))
end
-- one level less (debug); level 1 -> not forged
local function lower(sid)
    local r = cur[sid]
    if not r then return end
    if (r.level or 3) <= 1 then unforge(sid); return end
    r.level = (r.level or 3) - 1
    local it = by_sid()[sid]
    if it and it.item == r.item then write_enh(it.md, forged_state(r.level)); push_to_equipment({ it.md }) end
    remember_live()
end

------------------------------------------------------------------------
-- save / load. A save goes through several functions (SaveDataManager.save -> SaveDataManager.saveGameSaveData ->
-- ItemManager.saveGameSaveData, ItemManager.saveGameSaveDataTarget for further save files, fillStorageSaveData,
-- makeLoopSaveData). The forges come off when the first of them starts and go back on only when the outermost one has
-- finished; nothing else may put them back in between (savingNow). Every slot the game asked to save gets the list.
------------------------------------------------------------------------
local pendingSlots, applyAt, checkPending = {}, nil, false
local savingNow, saveDepth, saveKept = false, 0, nil
local function save_pre()
    if saveDepth == 0 then
        savingNow = true
        local ok, kept = pcall(strip_all)
        saveKept = ok and kept or copy(cur)
    end
    saveDepth = saveDepth + 1
end
local function save_post()
    saveDepth = math.max(0, saveDepth - 1)
    if saveDepth > 0 then return end
    local slots = {}
    for slot in pairs(pendingSlots) do db.slots[tostring(slot)] = copy(saveKept or {}); slots[#slots + 1] = tostring(slot) end
    pendingSlots = {}
    saveKept = nil
    savingNow = false
    if #slots > 0 then save_db() end
    pcall(apply_all)
end
pcall(function()
    local sm_t = sdk.find_type_definition("app.SaveDataManager")
    for _, m in ipairs({ "requestSave", "requestSaveSlot", "requestSaveManual" }) do
        pcall(sdk.hook, sm_t:get_method(m), function(args)
            local slot = sdk.to_int64(args[3]) & 0xFFFFFFFF
            if slot < 0x80000000 then pendingSlots[slot] = true end
        end, function(r) return r end)
    end
    for _, m in ipairs({ "save", "saveGameSaveData" }) do
        pcall(sdk.hook, sm_t:get_method(m), function() save_pre() end, function(r) save_post(); return r end)
    end
    local im_t = sdk.find_type_definition("app.ItemManager")
    for _, m in ipairs({ "saveGameSaveData", "saveGameSaveDataTarget", "fillStorageSaveData", "makeLoopSaveData" }) do
        pcall(sdk.hook, im_t:get_method(m), function() save_pre() end, function(r) save_post(); return r end)
    end
    sdk.hook(im_t:get_method("loadGameSaveData"), nil, function(r)
        local sm = sdk.get_managed_singleton("app.SaveDataManager")
        local ok, s = pcall(function() return sm:call("getLoadingGameSlotId") end)
        curSlot = ok and s or nil
        cur = copy(db.slots[tostring(curSlot)] or {})
        db.lastSlot = curSlot
        checkPending = true
        applyAt = os.clock() + 2
        return r
    end)
end)

-- scripts unloading (Reset scripts, or the mod removed mid-session): take the forges off, so the game's memory
-- matches the save file; the next script instance puts them back from db.live
pcall(re.on_script_reset, function() pcall(strip_all) end)


------------------------------------------------------------------------
-- online guard: the game uploads your main pawn AND a snapshot of your Arisen (equipment with upgrade level and
-- stats) from memory, built by app.OnlinePawnDataFormatter (updatePlaydataFrom..., getEquipSnapshot...,
-- makeToUploadValidationWork) and app.PawnServerController.registerSupportPawnUploadData. (The formatter's
-- SetContextWriterOnline... methods go the other way - downloaded pawn data into the game - and are not touched.) While any of those run,
-- every dragonforge is taken off (you, pawns, storage box) and put back right after, so the online data is built from
-- plain items. Every equipment list they build is checked afterwards: a DLC spoil with an upgrade in it counts as a leak.
------------------------------------------------------------------------
db.online = db.online or { builds = 0, leaks = 0 }
local onlineDepth = 0
local function cur_has_item(id) for _, r in pairs(cur) do if r.item == id then return true end end return false end
local function online_pre()
    if onlineDepth == 0 then pcall(strip_all) end
    onlineDepth = onlineDepth + 1
end
local function online_post()
    onlineDepth = math.max(0, onlineDepth - 1)
    -- never put forges back while a save is being written (saving triggers these builders too)
    -- (and not before the load check has read the save file's state)
    if onlineDepth == 0 and not savingNow and not checkPending then pcall(apply_all) end
end
-- check a List<ApiCurrenatEquipInfo>: returns DLC spoils with an upgrade, DLC spoils seen
local function leaks_in(list)
    local n, seen = 0, 0
    list_each(list, function(e)
        local info = e:get_field("ItemInfo")
        if not info then return end
        local raw = tostring(info:get_field("ItemId"))
        if not db.online.idSample then db.online.idSample = raw end
        local id = tonumber(raw) or tonumber(raw:match("(%d+)%s*$") or "") or tonumber(raw:match("(%d+)") or "")
        -- a smith upgrade shows as EnhanceNum > 0 and named step types. (UnlimitEnhanceNum is 4 for every appraised
        -- spoil in the unmodded game, so it says nothing.)
        local t0 = tostring(info:get_field("EnhanceType0") or "")
        local up = (info:get_field("EnhanceNum") or 0) + ((t0 ~= "" and t0 ~= "None" and t0 ~= "nil") and 1 or 0)
        if id and FORGE[id] then
            seen = seen + 1
            if up > 0 then n = n + 1 end
            db.online.samples = db.online.samples or {}
            if #db.online.samples < 16 then
                local function g(f) local ok, v = pcall(info.get_field, info, f); return ok and tostring(v) or "?" end
                table.insert(db.online.samples, string.format("%s %s: EnhanceNum %s, Unlimit %s, types %s/%s/%s, base %s, appraised %s, forged here %s",
                    raw, FORGE[id][2], g("EnhanceNum"), g("UnlimitEnhanceNum"), g("EnhanceType0"), g("EnhanceType1"), g("EnhanceType2"),
                    g("EnhanceTypeBaseName"), g("IsAppraised"), tostring(cur_has_item and cur_has_item(id) or "?")))
            end
        end
    end)
    return n, seen
end
local function owner_list(playdata)
    for _, f in ipairs(playdata:get_type_definition():get_fields()) do
        if f:get_type():get_full_name() == "app.PawnApiUserdata.OwnerData" then
            local od = playdata:get_field(f:get_name())
            local eq = od and od:get_field("Equips")
            return eq and eq:get_field("EquipInfo")
        end
    end
end
local function note_build(fn, leaks, seen)
    db.online.builds = (db.online.builds or 0) + 1
    db.online.last = os.date("%Y-%m-%d %H:%M:%S") .. " " .. fn
    db.online.byFn = db.online.byFn or {}
    local c = db.online.byFn[fn] or { calls = 0, checkedSpoils = 0 }
    c.calls = c.calls + 1
    c.checkedSpoils = c.checkedSpoils + (seen or 0)
    db.online.byFn[fn] = c
    if leaks and leaks > 0 then
        db.online.leaks = (db.online.leaks or 0) + leaks
        log(string.format("online data (%s): %d DLC spoil(s) with an upgrade got into it", fn, leaks))
    end
    save_db()
end
local function hook_online(tdname, match)
    local td = sdk.find_type_definition(tdname)
    if not td then return end
    for _, m in ipairs(td:get_methods()) do
        local name = m:get_name()
        if match(name) then
            local stack = {}
            pcall(sdk.hook, m, function(args)
                online_pre()
                local pd
                if name == "updatePlaydataFromOwnerData" then pcall(function() pd = sdk.to_managed_object(args[3]) end) end
                stack[#stack + 1] = { pd = pd }
            end, function(r)
                local st = table.remove(stack) or {}
                local leaks, seen = st.leaks, st.seen
                pcall(function()
                    if name == "getEquipSnapshotMyPawn" then leaks, seen = leaks_in(sdk.to_managed_object(r))
                    elseif st.pd then leaks, seen = leaks_in(owner_list(st.pd)) end
                end)
                online_post()
                pcall(note_build, name, leaks, seen)
                return r
            end)
        end
    end
end
hook_online("app.OnlinePawnDataFormatter", function(n)
    return n:find("^updatePlaydataFrom") or n:find("^getEquipSnapshot") or n == "makeToUploadValidationWork"
end)
hook_online("app.PawnServerController", function(n)
    return n == "registerSupportPawnUploadData" or n == "registerSupportPawnDismissal" or n == "registerSupportPawnLeaveParty"
        or n == "registerSupportPawnLost"
end)

local tick, firstLook, nextGuard = 0, true, 0
re.on_frame(function()
    tick = tick + 1
    -- items move between you, your pawns and the storage box at any time: re-check every 2 s
    -- (not before the load check has read the save file's state: it runs at applyAt)
    if next(cur) and not savingNow and not applyAt and not checkPending and os.clock() > nextGuard then nextGuard = os.clock() + 2; pcall(apply_all) end
    if ready.w + ready.a == 0 and tick % 60 == 0 then pcall(inject_tables) end
    -- started while a save is already loaded (scripts reset): continue with the live list of that slot
    if firstLook and tick > 120 then
        firstLook = false
        if #all_items() > 0 then
            curSlot = curSlot or db.lastSlot
            if db.live and db.live.slot == curSlot then cur = copy(db.live.items or {})
            else cur = copy(db.slots[tostring(curSlot)] or {}) end
            applyAt = os.clock()
        end
    end
    if applyAt and os.clock() > applyAt then
        applyAt = nil
        if checkPending then checkPending = false; pcall(check_save_file, curSlot) end
        pcall(adopt_untracked)
        local ok, n = pcall(apply_all)
        status = ok and string.format("save slot %s: %d dragonforged DLC item(s)", tostring(curSlot), n) or ("error: " .. tostring(n))
        remember_live()
    end
end)

------------------------------------------------------------------------
-- in-game notice: the game's own notice log (app.ui023301) shows an equipment notice for the forged item (its icon)
-- and our text replaces the game's: "<item> has been DRAGONFORGED!". Technique as in QuestCore by SonicaKP: let the
-- game build its UI element, then rewrite the element's text.
------------------------------------------------------------------------
local NOTICE_EQUIP = 17                -- app.ui023301.NoticeEnum.EquipStatusChange
local pendingNotices = {}         -- { item, text, untilT }, oldest first
local ourNotices = {}                  -- notice address -> { item, text }
local function notify_forged(item, name, level)
    local gm = sdk.get_managed_singleton("app.GuiManager")
    if not gm then return false end
    table.insert(pendingNotices, { item = item, untilT = os.clock() + 10,
        text = string.format("%s has been <COLOR D23A2A>DRAGONFORGED</COLOR>! (%d/3)", name, level) })
    return pcall(gm.call, gm, "addEquipStatusChangeNotice(System.Int32)", item)
end
pcall(function()
    local stack = {}
    sdk.hook(sdk.find_type_definition("app.ui023301.Notice"):get_method("setupText"), function(args)
        stack[#stack + 1] = sdk.to_int64(args[2])
    end, function(r)
        local addr = table.remove(stack)
        pcall(function()
            local notice = sdk.to_managed_object(addr)
            local data = notice and notice:get_field("Data")
            if not data then ourNotices[addr] = nil; return end
            local item, typ = data:get_field("ItemId"), data:get_field("NoticeType")
            local mine = ourNotices[addr]
            if mine and (mine.item ~= item or typ ~= NOTICE_EQUIP) then ourNotices[addr] = nil; mine = nil end
            if not mine and typ == NOTICE_EQUIP then
                for i, p in ipairs(pendingNotices) do
                    if os.clock() < p.untilT and item == p.item then
                        mine = { item = item, text = p.text }
                        ourNotices[addr] = mine
                        table.remove(pendingNotices, i)
                        break
                    end
                end
                for i = #pendingNotices, 1, -1 do if os.clock() >= pendingNotices[i].untilT then table.remove(pendingNotices, i) end end
            end
            local txt = mine and notice:get_field("TxtName")
            if txt then txt:call("set_Message", mine.text) end
        end)
        return r
    end)
end)

------------------------------------------------------------------------
-- dragon kills: when a dragon-type enemy dies by the hand of you or your pawns (or, with no attacker known, within
-- 60 m of you), one random equipped, not yet dragonforged DLC spoil of yours is dragonforged.
-- Dragon types: ch257 (Drake, Lesser Dragon, Fimbl) and ch258 (Dragon, Nex, Fallen Dragon and its variants).
------------------------------------------------------------------------
local DRAGON_PREFIX = { "ch257", "ch258" }
local lastDragonKill = -100
local function is_dragon(cid)
    local n = CHARA[cid]
    if not n then return false end
    for _, p in ipairs(DRAGON_PREFIX) do if n:sub(1, #p) == p then return true end end
    return false
end
local function chara_of(go)
    if not go then return nil end
    local ok, c = pcall(go.call, go, "getComponent(System.Type)", sdk.typeof("app.Character"))
    return ok and c or nil
end
local function is_party(chara)            -- you (ch000000_00) or a pawn (ch1xxxxx)
    local ok, cid = pcall(chara.call, chara, "get_CharaID")
    local n = ok and CHARA[cid]
    return n ~= nil and (n == PLAYER or n:sub(1, 3) == "ch1")
end
local function near_player(chara, dist)
    local cm = sdk.get_managed_singleton("app.CharacterManager")
    local p = cm and cm:get_field("<ManualPlayer>k__BackingField")
    local ok1, pp = pcall(function() return p:get_GameObject():get_Transform():get_Position() end)
    local ok2, pos = pcall(function() return chara:get_GameObject():get_Transform():get_Position() end)
    if not (ok1 and ok2 and pp and pos) then return false end
    return (pos - pp):length() <= dist
end

-- one random equipped DLC spoil of yours below level 3 gains a dragonforge level; returns its name or nil
local function forge_random(reason)
    local pick = {}
    for _, it in ipairs(all_items()) do
        local r = cur[tostring(it.sid)]
        if it.chara == PLAYER and it.equipped and FORGE[it.item] and (not r or (r.level or 3) < 3) then pick[#pick + 1] = it end
    end
    if #pick == 0 then log(reason .. " - every equipped DLC spoil is at dragonforge level 3"); status = "every equipped DLC spoil is at level 3"; return nil end
    local it = pick[math.random(#pick)]
    local level = raise(it)
    notify_forged(it.item, FORGE[it.item][2], level)
    status = string.format("%s: dragonforge level %d/3", FORGE[it.item][2], level)
    log(string.format("%s - %s dragonforged (%d/3)", reason, FORGE[it.item][2], level))
    return FORGE[it.item][2]
end
-- chance (%) per dragon type for an item at forge level 0, 1 and 2 to gain a level; variants count as their base
-- enemy (ch257000_50 = Drake, ch258002_30 Rancorous Dragon Carcass = Fallen Dragon, ...)
-- (ch257002 exists only in cutscenes; ch258000 "Dragon" is the main story boss)
local DRAGON_CHANCE = {
    { "ch257000", "Drake",         { 10, 15, 25 } },
    { "ch257001", "Lesser Dragon", { 12, 18, 30 } },
    { "ch257003", "Fimbl",         { 30, 40, 55 } },
    { "ch258000", "Dragon",        { 100, 100, 100 } },
    { "ch258001", "Nex",           { 100, 100, 100 } },
    { "ch258002", "Fallen Dragon", { 100, 100, 100 } },
}
local function dragon_chance(id)
    for _, d in ipairs(DRAGON_CHANCE) do if id:sub(1, #d[1]) == d[1] then return d[3], d[2] end end
    return { 10, 15, 25 }, id
end
-- every equipped DLC spoil of yours below level 3 rolls on its own, like in the first game
local function on_dragon_killed(id)
    if os.clock() - lastDragonKill < 5 then return end          -- one kill, several notifications
    lastDragonKill = os.clock()
    local chances, name = dragon_chance(id)
    local results = {}
    for _, it in ipairs(all_items()) do
        if (it.chara == PLAYER or it.chara == MAIN_PAWN) and it.equipped and FORGE[it.item] then
            local r = cur[tostring(it.sid)]
            local level = r and (r.level or 3) or 0
            if level < 3 then
                local chance = chances[level + 1] or 0
                if math.random(100) <= chance then
                    local new = raise(it)
                    notify_forged(it.item, FORGE[it.item][2] .. (it.chara == MAIN_PAWN and " (your pawn)" or ""), new)
                    results[#results + 1] = string.format("%s -> %d/3 (%d%%)", FORGE[it.item][2], new, chance)
                else
                    results[#results + 1] = string.format("%s stays %d/3 (%d%%)", FORGE[it.item][2], level, chance)
                end
            end
        end
    end
    if #results == 0 then log(name .. " slain - every equipped DLC spoil is at level 3 (or none equipped)"); return end
    status = name .. " slain: " .. table.concat(results, ", ")
    log(status)
end

pcall(function()
    sdk.hook(sdk.find_type_definition("app.Character"):get_method("onDieFromAttack"), function(args)
        pcall(function()
            local dead = sdk.to_managed_object(args[2])
            local cid = dead:call("get_CharaID")
            if not is_dragon(cid) then return end
            local info = sdk.to_managed_object(args[3])
            local attacker = info and chara_of(info:call("get_AttackOwnerObject"))
            if (attacker and is_party(attacker)) or (not attacker and near_player(dead, 60)) then
                on_dragon_killed(CHARA[cid])
            end
        end)
    end, function(r) return r end)
end)
-- fallback: the game's own defeat counter, for dragons that die some other way
pcall(function()
    sdk.hook(sdk.find_type_definition("app.EnemyDeadCountManager"):get_method("addDeadCount"), function(args)
        pcall(function()
            local cid = sdk.to_int64(args[3]) & 0xFFFFFFFF
            if is_dragon(cid) then on_dragon_killed(CHARA[cid]) end
        end)
    end, function(r) return r end)
end)

------------------------------------------------------------------------
-- item cards (ItemIcon3Ref): one hook per card-building method remembers which item the card shows; while the card
-- of an UNFORGED spoil is built, the game is told the item has no upgrade data, so it draws no upgrade rings
------------------------------------------------------------------------
local ICON_T = sdk.find_type_definition("app.GUIBase.ItemIcon3Ref")
local cardItem = {}            -- card address -> { item }
local restore = {}             -- card address -> list of { ctrl, property, old value }
local function unhide(addr)
    local r = restore[addr]
    if not r then return end
    for i = #r, 1, -1 do pcall(r[i][1].call, r[i][1], "set_" .. r[i][2], r[i][3]) end
    restore[addr] = nil
end
local function peek(ptr)       -- item id + upgrade level of a StorageData argument
    local ok, vt = pcall(sdk.to_valuetype, ptr, "app.ItemDefine.StorageData")
    if not ok or not vt then return nil end
    local en = vt:get_field("_Enhance")
    return vt:get_field("_ItemId"), en and en:get_field("_Num") or 0
end
for _, m in ipairs(ICON_T:get_methods()) do
    local name = m:get_name()
    if name == "setup" or name == "dispCategory" then
        local okP, p1 = pcall(function() return m:get_num_params() > 0 and m:get_param_types()[1]:get_full_name() or "" end)
        if not okP then p1 = "" end
        if p1 == "app.ItemDefine.StorageData" or p1 == "app.ItemCommonParam" or p1 == "System.Int32" then
            local stack = {}
            pcall(sdk.hook, m, function(args)
                local hideFor = false
                pcall(function()
                    local addr = sdk.to_int64(args[2])
                    local item, num
                    if p1 == "app.ItemDefine.StorageData" then item, num = peek(args[3])
                    elseif p1 == "app.ItemCommonParam" then
                        local o = sdk.to_managed_object(args[3]); item = o and o:get_field("_Id")
                    else item = sdk.to_int64(args[3]) & 0xFFFFFFFF end
                    unhide(addr)
                    cardItem[addr] = item and { item = item } or nil
                    if num and num ~= 4 and FORGE[item] then
                        hideFor = item
                        uiUnforged[item] = (uiUnforged[item] or 0) + 1
                    end
                end)
                stack[#stack + 1] = hideFor
            end, function(r)
                local item = table.remove(stack)
                if item then
                    uiUnforged[item] = (uiUnforged[item] or 1) - 1
                    if uiUnforged[item] <= 0 then uiUnforged[item] = nil end
                end
                return r
            end)
        end
    end
end

-- a dragonforged spoil's card shows only the dragonforge mark: the card (ItemIcon3Ref.PnlUpgrade) has four mark
-- images; tex_UpgradeIcon2 is the dragonforge one, the other three would show smith styles and are hidden
local SMITH_MARKS = { "tex_UpgradeIcon", "tex_UpgradeIcon0", "tex_UpgradeIcon1" }
local function gui_children(ctrl)
    local out = {}
    local ok, c = pcall(ctrl.call, ctrl, "get_Child")
    local guard = 0
    while ok and c and guard < 64 do
        out[#out + 1] = c
        ok, c = pcall(c.call, c, "get_Next")
        guard = guard + 1
    end
    return out
end
-- dragonforge mark colour per level, through the mark's Color property (via.Color, 0-255 per channel; the only colour
-- setting that works on this element - it multiplies the red picture): 1 teal, 2 orange, 3 magenta
local VIA_COLOR = sdk.find_type_definition("via.Color")
local DEFAULT_TINT = { [1] = { 29, 254, 198 }, [2] = { 255, 255, 6 }, [3] = { 255, 2, 255 } }
if db.tintVer ~= 3 then db.tint = copy(DEFAULT_TINT); db.tintVer = 3 end
-- byte order of via.Color.rgba, learned from the game's own Red preset
local RED_LOW = true
pcall(function() RED_LOW = (VIA_COLOR:get_field("Red"):get_data(nil):get_field("rgba") & 0xFF) == 0xFF end)
local function make_colour(rgb)
    local r, g, b = rgb[1] & 0xFF, rgb[2] & 0xFF, rgb[3] & 0xFF
    local v = RED_LOW and (r | (g << 8) | (b << 16) | (0xFF << 24)) or ((r << 24) | (g << 16) | (b << 8) | 0xFF)
    local c = ValueType.new(VIA_COLOR)
    c:set_field("rgba", v)
    return c
end
local cardLevel = {}           -- card address -> forge level (from the step marks the game draws)
local change                   -- set below
local tintInfo, gameColour = "no forged card drawn yet", "?"
local function tint_mark(addr, mark, level)
    local t = db.tint[level] or db.tint[tostring(level)]
    if not t then tintInfo = "no colour set for level " .. tostring(level); return end
    pcall(function()
        local v = mark:call("get_Color"):get_field("rgba")
        gameColour = RED_LOW and string.format("%d, %d, %d", v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF)
            or string.format("%d, %d, %d", (v >> 24) & 0xFF, (v >> 16) & 0xFF, (v >> 8) & 0xFF)
    end)
    tintInfo = string.format("level %d: colour %d, %d, %d -> %s", level, t[1], t[2], t[3], tostring(change(addr, mark, "Color", make_colour(t))))
end
local function hide_smith_marks(card, addr)
    local up = card:get_field("PnlUpgrade")
    if not up then return end
    local by = {}
    for _, c in ipairs(gui_children(up)) do
        local ok, n = pcall(c.call, c, "get_Name")
        if ok and n then by[tostring(n)] = c end
    end
    local level = cardLevel[addr] or 3
    if not by["tex_UpgradeIcon2"] then tintInfo = "dragonforge mark element not found on the card"
    else local ok, e = pcall(tint_mark, addr, by["tex_UpgradeIcon2"], level); if not ok then tintInfo = "tint error: " .. tostring(e) end end
    for _, n in ipairs(SMITH_MARKS) do
        local m = by[n]
        if m then
            restore[addr] = restore[addr] or {}
            table.insert(restore[addr], { m, "Visible", true })
            pcall(m.call, m, "set_Visible", false)
        end
    end
end
change = function(addr, ctrl, prop, value)
    local ok, old = pcall(ctrl.call, ctrl, "get_" .. prop)
    if not ok then return "no getter" end
    restore[addr] = restore[addr] or {}
    table.insert(restore[addr], { ctrl, prop, old })
    local ok2, e = pcall(ctrl.call, ctrl, "set_" .. prop, value)
    return ok2 and "ok" or ("error " .. tostring(e))
end
pcall(function()
    local pending = nil
    sdk.hook(ICON_T:get_method("setUgIcon"), function(args)
        pending = nil
        local typ = sdk.to_int64(args[4]) & 0xFFFFFFFF
        local c = cardItem[sdk.to_int64(args[2])]
        -- the step marks (types 0..3) come first: their type is the forge level
        if typ ~= ENH_UNLIMIT and c and c.item and FORGE[c.item] then cardLevel[sdk.to_int64(args[2])] = math.min(typ, 2) + 1 end
        -- the dragonforge mark (type 4) is drawn last; a spoil only has marks if this mod dragonforged it
        if typ == ENH_UNLIMIT and c and c.item and FORGE[c.item] then
            pending = { card = sdk.to_managed_object(args[2]), addr = sdk.to_int64(args[2]) }
        end
    end, function(r)
        local p = pending
        pending = nil
        if p then pcall(hide_smith_marks, p.card, p.addr) end
        return r
    end)
end)

